// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] calldata tos, uint256[] calldata vs) public {
        // Restrict input to the admissible domain that avoids reverting on inputs,
        // but keep it wide enough so the fuzzer can find the differing return.
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // The `validAddress` modifier rejects 0x0 and `address(this)`.
        // For the fuzzed `tos` and the `contract_address` we choose a known
        // simple address that will NOT revert on a low-level call. Since any
        // fuzzed address is an EOA and low-level calls to EOAs always succeed,
        // we can use a fresh EOA as the target contract.
        address target = address(uint160(uint256(keccak256(abi.encodePacked("target")))));
        vm.assume(target != address(0x0));
        vm.assume(target != address(c));

        // Ensure `tos` entries are valid according to the future ERC20 logic:
        // they must not be 0x0 and not be the c contract. The modifier also
        // checks the `contract_address` (target), which we already guarantee.
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
        }

        bool result = c.transfer(target, tos, vs);

        // For the CORRECT contract the call always returns `true` when it does
        // not revert. The bugged version returns `false`. Therefore the
        // universal property is: the return value must be true.
        assertTrue(result);
    }
}

