pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory vs) public {
        // Bound the array lengths to keep the domain wide but manageable
        vm.assume(tos.length > 0);
        vm.assume(tos.length < 100);
        vm.assume(vs.length == tos.length);

        // Deploy a helper that succeeds on any low-level call (to satisfy require(_s))
        Helper helper = new Helper();

        // Filter out invalid addresses
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
            vm.assume(tos[i] != address(helper));
            vm.assume(tos[i] != address(c));
        }

        // Call transfer and capture the return value
        bool ret = c.transfer(address(helper), tos, vs);

        // Assert: the return value must be true (last call succeeded, require(_s) ensures it)
        assertTrue(ret);
    }
}

// Minimal helper that always returns true on any low-level call
contract Helper {
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
}

