pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        // Keep inputs within admissible domain
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // Bound lengths to avoid blowing up gas
        uint len = tos.length;
        vm.assume(len <= 10);
        for (uint i = 0; i < len; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
            vm.assume(vs[i] > 0);
        }

        // Deploy a helper that always succeeds on the external call so the loop completes.
        // The helper receives the transferFrom selector call and returns true.
        Helper h = new Helper();

        // Drive c with the helper as the contract_address
        bool ret = c.transfer(address(h), tos, vs);

        // The reference C returns true (since all calls succeed).
        // The mutant returns false.
        assertTrue(ret);
    }
}

contract Helper {
    // This fallback handles the low-level call with transferFrom selector and returns success.
    fallback(bytes calldata) external payable returns (bytes memory) {
        // return abi.encode(true) for uint8 to match expected success
        return abi.encode(true);
    }
}

