        for (uint i = 0; i < vs.length; i++) {
            vm.assume(vs[i] > 0);
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != contract_address);
        }

        // Deploy a mock ERC20 that always returns true on transferFrom to satisfy the require(_s) in the loop
