pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // Deploy a helper that accepts the transferFrom call successfully
        AcceptingHelper helper = new AcceptingHelper();
        bool ok = false;
        try c.transfer(address(helper), tos, vs) returns (bool ret) {
            ok = true;
            assertTrue(ret);
        } catch {
            ok = false;
        }
        // If the call completed, the return value must be true.
        // The assertTrue above already checks this for the success case.
        // If it reverted, the property trivially holds (no return value to check).
        // To satisfy the single assertion rule, assert that the invariant holds:
        // whenever the call succeeds, the return value is true.
        // We re-express this as: (not ok) or (ret == true).
        // Since we can't capture ret outside try/catch without a storage variable,
        // we use a storage flag to capture the result.
        // Simpler: we just assert that the return value is true when the call succeeds,
        // and the fuzzer will find a case where the buggy version succeeds but returns false.
    }
}

contract AcceptingHelper {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}

